[central_hub] {
  "spatial_concept": {
    "theme_name": "水光与河岸的时空谷",
    "form_description": "滨水博物馆的一层至四层通高中庭，宽度从底层逐渐收束至顶层，形成“河谷”的形态；双层通高的玻璃幕墙与天窗引入滨水光带，底层中央设置浅水镜面（带溢流水槽），墙面采用仿滨岸岩层的浅浮雕槽板与微纹理铝板，引导视线沿水流方向汇聚；南北两侧各布置一条弧形环廊，环廊下方设缓步平台与看台，形成层次化观演界面。",
    "atmosphere": "明亮、温润，具仪式感与科技感，天窗变化光带模拟水岸昼夜节律，营造可沉浸式公共文化场域。"
  },
  "scale_reference": {
    "height_suggestion": "约24–28m，贯穿1–4层（建议以24–26m为基准）。",
    "area_suggestion": "约1800–2500㎡核心中庭区（不含环廊与看台）。",
    "rationale": "依据博物馆设计规范在中庭周边与入口处布置门厅、问询、寄存、轮椅与儿童车等观众服务功能；同时参考Steinhardt的“自然光入口—导视—分派”逻辑、Dornier的通高透明界面与分层展陈引导策略、以及Biomuseo“公共室外中庭—彩色遮阳”的气候适应做法，确定高度与面积的量级以确保人流集散与视线通达；24m级别通高与约2000㎡级别空间能够容纳大型标志物与垂直交通枢纽，同时便于天窗引入柔和漫反射光并通过浅水镜面进行湿度缓解。"
  },
  "circulation_hub": {
    "vertical_transport": "采用“弧形环廊＋双扶梯＋一台飞天梯＋一座折返主梯”的复合动线：主入口在1层设折返主梯与2组并列扶梯；2层设飞天梯（跨层电梯）与2组扶梯组成“上行专用带”；3层至4层布置2部扶梯形成“下行回带”。中庭北侧设可容纳轮椅与儿童车的1.8m宽缓坡，坡度不大于5%；飞天梯停靠处设置可移动指挥台，便于人流调度。",
    "visual_connection": "环廊采用“镂空格栅＋穿孔金属”构造，底部与中庭形成半通透边界；上层展廊边缘布置连续看台与小尺度开窗，视线可达底层水景与水幕；顶层设观景桥与半室外露台，将水岸视野引入中庭；各层展厅入口通过导视灯光与声学微提示与中庭相连，形成“上观下览、下观上展”的多重可视关系。"
  },
  "feature_element": {
    "type": "“水脉光环”多媒体互动装置",
    "description": "中庭中央悬挂一对直径约8–10m的金属环形装置，表面为镜面不锈钢与内嵌LED点阵；环形下方设置细线水幕与雾化喷嘴，形成“水光双环”效果。该装置可展示科普内容：如雨洪网络、滨水生物迁徙、海平面变化与碳循环等数据与影像，环形内外环LED同步闪烁以模拟水位波纹；配合声学与投影，形成可互动的“滨水生态可视化”。材质与构造借鉴Dornier的全高度透明与轻量化表达，同时以BIM深化构件模块化与检修可达性；环下设浅水镜面（约300–400㎡，水位20cm）与溢流水槽，有效缓解环境湿度并作为疏散视觉锚点。"
  },
  "physical_environment": {
    "natural_lighting": "中庭东、南、西三面采用双层呼吸式幕墙＋可开窗，夏季使用内遮阳与外遮阳（可调内遮阳）；顶层设多段式天窗并布置漫反射扩散板与双层夹胶玻璃，防止眩光与热聚集；在滨水侧设置竖向百叶以控制入射角；水幕与镜面共同提升环境湿度与光线柔化。",
    "ventilation_strategy": "自然通风为主：利用天窗高窗开启（热压驱动）、中庭开口与幕墙可开窗形成穿堂风；设置中置式机械送排风与全热回收系统以应对季风与潮气；与消防排烟系统协同，在顶部配置电动排烟窗以满足烟控要求；浅水镜面区域增加独立除湿与防霉监测。"
  }
}
